export const LORE_ZONE_WEIGHTS: Record<ScavengeZoneType, number> = {
  ruins: 0.20,
  wasteland: 0.12,
  underhive: 0.18,
  industrial: 0.15,
  military: 0.22,
  anomaly: 0.30,
};

export const LORE_RARITY_WEIGHTS: Record<LoreRarity, number> = {
  common: 45,
  uncommon: 35,
  rare: 15,
  legendary: 5,
};

export function getLoreById(id: string): LoreEntry | undefined {
  return LORE_ENTRIES.find((e) => e.id === id);
}

export function getUndiscoveredLore(discovered: string[], zoneType: ScavengeZoneType): LoreEntry[] {
  return LORE_ENTRIES.filter(
    (e) => !discovered.includes(e.id) && e.zoneTypes.includes(zoneType)
  );
}

export function rollLoreRarity(dangerBonus: number): LoreRarity {
  const adjusted = {
    common: Math.max(5, LORE_RARITY_WEIGHTS.common - dangerBonus * 0.3),
    uncommon: LORE_RARITY_WEIGHTS.uncommon + dangerBonus * 0.1,
    rare: LORE_RARITY_WEIGHTS.rare + dangerBonus * 0.12,
    legendary: LORE_RARITY_WEIGHTS.legendary + dangerBonus * 0.08,
  };
  const total = adjusted.common + adjusted.uncommon + adjusted.rare + adjusted.legendary;
  const roll = Math.random() * total;
  let acc = 0;
  for (const r of ["common", "uncommon", "rare", "legendary"] as LoreRarity[]) {
    acc += adjusted[r];
    if (roll < acc) return r;
  }
  return "common";
}
